(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[1540],{4008:(e,l,a)=>{"use strict";a.r(l),a.d(l,{data:()=>s});const s={key:"v-2350773f",path:"/pages/self-daily/daily-log/2026-02-20/",title:"",lang:"zh-CN",frontmatter:{sidebar:!1},excerpt:"",headers:[{level:3,title:"外公在今日凌晨去世了。",slug:"外公在今日凌晨去世了。",children:[]}],filePathRelative:"pages/self-daily/daily-log/2026-02-20/README.md",git:{updatedTime:1772084788e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:1}]}}},3179:(e,l,a)=>{"use strict";a.r(l),a.d(l,{default:()=>n});var s=a(6252);const t=(0,s.Wm)("h3",{id:"外公在今日凌晨去世了。"},[(0,s.Wm)("a",{class:"header-anchor",href:"#外公在今日凌晨去世了。"},"#"),(0,s.Uk)(" 外公在今日凌晨去世了。")],-1),r=(0,s.Wm)("p",null,"   外公在今日凌晨 4 点去世了，享年 84 岁。今天是大年初二，早上五点我还在睡梦中我妈打来电话说外公起来上厕所中风摔了一跤，我风尘仆仆穿好衣服，背着挎包和爸妈立即前往外公家。在路上快到外公家的时候，看到表哥和舅舅已经拖着外公往医院赶，我们也立即转弯往医院赶，这个过程中由于我穿了一件毛衣换了一个车，我的挎包不知在何时弄丢了。来到医院，外公的中风症状已经很严重了，左边身体不能动了，左侧眼睛也一直斜视无法回正。左侧身体完全没有知觉，医生赶忙过来抢救，一开始打了溶血栓针，外公之前打过一次，之前症状没有这么严重，打了一针后就缓解了，这一次打完针后没有效果，医生说要准备做一个介入手术，用管道从大腿通到大脑，拿出血栓。但是由于已经过去五六个小时了脑细胞还是会死亡。具体效果就需要看恢复情况了。我们同意了手术，手术大概进行了三个小时。手术后外公被推进了重症监护室，晚上小舅舅和姨夫在那里照看外公，第二天我和谢旺再去看外公的时候外公左边身体还是不能动但是意识还算清醒，外公说的话我还能听清，要我介绍对象给钟雨，这应该是外公对我最后的嘱咐了，当我们都以为外公在慢慢恢复的时候，当晚 10 点左右，我妈又打来电话说外公有点脑出血，快不行了，我急忙忙接上钟雨往医院赶，来到医院外公已经处于昏迷状态了。外公清醒的时候一直喊着小平我大舅的名字，一直说要回家，外公插食管的时候我在身边，那么长的食管插到胃里，外公一定很难受吧，外公一直想起来上厕所我们没有让他起来。外公想回家我们怕耽误治疗没有如愿。后面外公昏迷了，医生说不太行了。舅舅决定马上弄回家，外公应该是想家了 想回家了。这几天外婆的身体也一直不好 一直在打针，外婆也在医院住着院。外婆来外公的病床前看了两次外公。外婆哭了，舅舅哭了，我也哭了。凌晨 1 点怕外婆有个闪失我们叫来了外婆的妹妹来陪外婆，外婆一直哭，凌晨 2 点我们把外公送回了家，我们拔掉了氧气管，食管，外公一直处于昏迷的状态。外公可能可以听到，但永远没有了回应。外公的体温在慢慢降低，到了凌晨 4 点 外公走完了人生的最后一刻，享年 84 岁。凌晨 4 点外婆可能是由于心灵感应，也在那个时间段大哭了起来。外公的亲外甥说，差不多这个时候他梦见了一个大盘子被摔碎了，被惊吓到一晚没睡。亲情血缘或许就是这样，被羁绊被关联。    我们一群人簇拥长跪在地上，眼泪不停的滴落，妈妈一直在呼喊着她的父亲，从没见过一生要强的妈妈会哭成一个泪人，像一个小女孩在不停呼唤着自己的父亲，她父亲再也不会应答了。我妈走娘家走得勤，小时候我不知和我妈走了多少趟外公家。那时总会带一堆吃得给外公外婆吃，外公家有好多水果树，杨梅树，桃树，枇杷树，李子树，板栗树，柚子树。之前舅舅家还有一颗葡萄树。小时候也非常开心来外公家玩，外公经常摘水果带回来给我们吃。我妈作为长女，是外公的小棉袄，小时候外公管得严，我妈四个兄弟姐妹都害怕外公。外公最喜欢我妈回娘家然后父女两喝上几杯啤酒，外公和我妈总是有说不完的话。妈妈趴在外公的床边哭红了眼，脚一直跪着久了没了知觉，鼻子也冰冷没有知觉。妈妈诉说着外公的不易，外公从小没有妈，小小年纪有三个妈，一个奶妈、一个后妈、一个亲妈。那个时候还是抗日战争年代，外公的亲生母亲生外公没多久就去世了，外公有一个同父同母的亲姐姐。因为没奶水，外公的父亲怕养不活外公，于是将外公送给了桥头的一户人家那里，就是外公的奶妈家。但是由于奶妈家也穷一直问外公的父亲要粮食来养外公，于是一年多后外公又被接了回来。后面外公的父亲又娶了一个后妈，生下了外公的两个弟弟和一个妹妹。外公的弟弟妹妹比外公小十几岁，外公十几岁拉扯弟弟妹妹长大，吃了非常多的苦。外公当了十几年的村组长，一生正直，公正无私，在集体那会，外公由于长得高大，在村里扮演着 包青天一样的角色，处理各种邻里纠纷，家庭分家等等。外公是五十几年的老党员，村里很多人入党都是外公作的介绍人。外公喜欢关注国家大事，外公喜欢看电视 喜欢看新闻联播。外公是当年的红卫兵，毛主席的战士。外公走了，去找毛主席了，他永远得离开了我们。我们知道他去找他妈妈他爸爸去了，从小没有亲生母亲疼爱的外公，终于可以和他的母亲相拥了，可以和他的姐姐见面了，那些早早离世的亲人都在天堂等着外公。    那个年代的人过得真苦啊，我的母亲在家做姑娘的时候也是苦，外公当村组长不能干活挣工分，都靠母亲带着大舅不停得干不停的做。那时家里还养了鱼，一年到头一直欠队里钱。养的猪都要用来还账。听母亲回忆，最好的一年一家人挣了一块三毛四分钱，没有欠队里钱，一家人都非常开心。那时候养鱼，母亲和外公经常十一月的天气，在池塘里光脚去喂鱼去拖鱼苗，母亲的脚一直有风湿不通血，不能洗冷水就是这个时候落下的病根。外公走了，缅怀外公。外公也是有福之人，村里去年刚建好的祠堂，外公成了在这祭奠的第一个老人。外公走得安详，走得风光，希望您在天上保佑我们后世子孙，也保佑外婆身体健康。",-1),i=(0,s.Uk)("外公的入党五十周年纪念徽章 "),d=(0,s.Uk)(" 外公的入党五十周年纪念徽章 "),n={render:function(e,l){return(0,s.wg)(),(0,s.j4)(s.HY,null,[t,r,(0,s.Wm)("p",null,[i,(0,s.Wm)("img",{src:e.$withBase("./images/self-daily/party50th.jpg")},null,8,["src"]),d,(0,s.Wm)("img",{src:e.$withBase("./images/self-daily/party50thBook.jpg")},null,8,["src"])])],64)}}}}]);